package com.smartcart.model;

import java.io.Serializable;

/**
 * Represents a warning generated by the Cart Mistake Detector.
 */
public class MistakeAlert implements Serializable {
    private static final long serialVersionUID = 1L;

    public enum AlertType {
        DUPLICATE_ITEM,
        HIGH_QUANTITY,
        UNNECESSARY_PURCHASE,
        REDUNDANT_ACCESSORY
    }

    private String id;
    private AlertType type;
    private String title;
    private String message;
    private String explanation;
    private int productId;
    private String productName;
    private String severity; // "HIGH", "MEDIUM", "LOW"
    private boolean dismissed;

    public MistakeAlert() {}

    public MistakeAlert(String id, AlertType type, String title, String message, 
                        String explanation, int productId, String productName, String severity) {
        this.id = id;
        this.type = type;
        this.title = title;
        this.message = message;
        this.explanation = explanation;
        this.productId = productId;
        this.productName = productName;
        this.severity = severity;
        this.dismissed = false;
    }

    public String getId() { return id; }
    public void setId(String id) { this.id = id; }

    public AlertType getType() { return type; }
    public void setType(AlertType type) { this.type = type; }

    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }

    public String getMessage() { return message; }
    public void setMessage(String message) { this.message = message; }

    public String getExplanation() { return explanation; }
    public void setExplanation(String explanation) { this.explanation = explanation; }

    public int getProductId() { return productId; }
    public void setProductId(int productId) { this.productId = productId; }

    public String getProductName() { return productName; }
    public void setProductName(String productName) { this.productName = productName; }

    public String getSeverity() { return severity; }
    public void setSeverity(String severity) { this.severity = severity; }

    public boolean isDismissed() { return dismissed; }
    public void setDismissed(boolean dismissed) { this.dismissed = dismissed; }
}
